9860	void Plater::priv::actualize_slicing_warnings(const PrintBase &print)
9861	{
9862	    std::vector<ObjectID> ids = print.print_object_ids();
9863	    if (ids.empty()) {
9864	        clear_warnings();
9865	        return;
9866	    }
9867	    ids.emplace_back(print.id());
9868	    std::sort(ids.begin(), ids.end());
9869	    notification_manager->remove_slicing_warnings_of_released_objects(ids);
9870	    notification_manager->set_all_slicing_warnings_gray(true);
9871	}
9872	void Plater::priv::actualize_object_warnings(const PrintBase& print)
9873	{
9874	    std::vector<ObjectID> ids;
9875	    for (const ModelObject* object : print.model().objects )
9876	    {
9877	        ids.push_back(object->id());
9878	    }
9879	    std::sort(ids.begin(), ids.end());
9880	    notification_manager->remove_simplify_suggestion_of_released_objects(ids);
9881	}
9882	void Plater::priv::clear_warnings()
9883	{
9884	    notification_manager->close_slicing_errors_and_warnings();
9885	    this->current_warnings.clear();
9886	}
9887	bool Plater::priv::warnings_dialog()
9888	{
9889	    if (current_warnings.empty())
9890	        return true;
9891	    std::string text = _u8L("There are warnings after slicing models:") + "\n";
9892	    for (auto const& it : current_warnings) {
9893	        size_t next_n = it.first.message.find_first_of('\n', 0);
9894	        text += "\n";
9895	        if (next_n != std::string::npos)
9896	            text += it.first.message.substr(0, next_n);
9897	        else
9898	            text += it.first.message;
9899	    }
9900	    //text += "\n\nDo you still wish to export?";
9901	    MessageDialog msg_window(this->q, from_u8(text), _L("warnings"), wxOK);
9902	    const auto    res = msg_window.ShowModal();
9903	    return res == wxID_OK;
9904	
9905	}
