9909	{
9910	    BOOST_LOG_TRIVIAL(debug) << __FUNCTION__ << boost::format(": enter, m_ignore_event %1%, status %2%")%m_ignore_event %evt.status();
9911	    //BBS:ignore cancel event for some special case
9912	    if (m_ignore_event)
9913	    {
9914	        m_ignore_event = false;
9915	        BOOST_LOG_TRIVIAL(info) << __FUNCTION__ << boost::format(": ignore this event %1%") % evt.status();
9916	        return;
9917	    }
9918	    //BBS: add project slice logic
9919	    bool is_finished = !m_slice_all || (m_cur_slice_plate == (partplate_list.get_plate_count() - 1));
9920	
9921	    //BBS: slice .gcode.3mf file related logic, assign is_finished again
9922	    bool only_has_gcode_need_preview = false;
9923	    auto plate_list = this->partplate_list.get_plate_list();
9924	    bool has_print_instances = false;
9925	    for (auto plate : plate_list)
9926	        has_print_instances = has_print_instances || plate->has_printable_instances();
9927	    if (this->model.objects.empty() && !has_print_instances)
9928	        only_has_gcode_need_preview = true;
9929	    if (only_has_gcode_need_preview && m_slice_all_only_has_gcode) {
9930	        is_finished = (m_cur_slice_plate == (partplate_list.get_plate_count() - 1));
9931	        if (is_finished)
9932	            m_slice_all_only_has_gcode = false;
9933	    }
9934	
9935	    // Stop the background task, wait until the thread goes into the "Idle" state.
9936	    // At this point of time the thread should be either finished or canceled,
9937	    // so the following call just confirms, that the produced data were consumed.
9938	    this->background_process.stop();
9939	    notification_manager->set_slicing_progress_export_possible();
9940	
9941	    // Reset the "export G-code path" name, so that the automatic background processing will be enabled again.
9942	    this->background_process.reset_export();
9943	    // This bool stops showing export finished notification even when process_completed_with_error is false
9944	    bool has_error = false;
9945	    if (evt.error()) {
9946	        auto message = evt.format_error_message();
9947	        if (evt.critical_error()) {
9948	            if (q->m_tracking_popup_menu) {
9949	                // We don't want to pop-up a message box when tracking a pop-up menu.
9950	                // We postpone the error message instead.
9951	                q->m_tracking_popup_menu_error_message = message.first;
9952	            } else {
9953	                show_error(q, message.first, message.second.size() != 0 && message.second[0] != 0);
9954	                notification_manager->set_slicing_progress_hidden();
9955	            }
9956	        } else {
9957	            std::vector<const ModelObject *> ptrs;
9958	            for (auto oid : message.second)
9959	            {
9960	                const PrintObject *print_object = this->background_process.m_fff_print->get_object(ObjectID(oid));
9961	                if (print_object) { ptrs.push_back(print_object->model_object()); }
9962	            }
9963	            notification_manager->push_slicing_error_notification(message.first, ptrs);
9964	        }
9965	        if (evt.invalidate_plater())
9966	        {
9967	            // BBS
9968	#if 0
9969	            const wxString invalid_str = _L("Invalid data");
9970	            for (auto btn : { ActionButtonType::abReslice, ActionButtonType::abSendGCode, ActionButtonType::abExport })
9971	                sidebar->set_btn_label(btn, invalid_str);
9972	#endif
9973	            process_completed_with_error = partplate_list.get_curr_plate_index();;
9974	        }
9975	        has_error = true;
9976	        is_finished = true;
9977	    }
9978	    if (evt.cancelled()) {
9979	        BOOST_LOG_TRIVIAL(info) << __FUNCTION__ << boost::format(", cancel event, status: %1%") % evt.status();
9980	        this->notification_manager->set_slicing_progress_canceled(_u8L("Slicing Canceled"));
9981	        is_finished = true;
9982	    }
9983	
9984	    //BBS: set the current plater's slice result to valid
9985	    if (!this->background_process.empty())
9986	        this->background_process.get_current_plate()->update_slice_result_valid_state(evt.success());
9987	
9988	    //BBS: update the action button according to the current plate's status
9989	    bool ready_to_slice = !this->partplate_list.get_curr_plate()->is_slice_result_valid();
9990	
9991	    // BBS
9992	#if 0
9993	    this->sidebar->show_sliced_info_sizer(evt.success());
9994	#endif
9995	
9996	    // This updates the "Slice now", "Export G-code", "Arrange" buttons status.
9997	    // Namely, it refreshes the "Out of print bed" property of all the ModelObjects, and it enables
9998	    // the "Slice now" and "Export G-code" buttons based on their "out of bed" status.
9999	    //BBS: remove this update here, will be updated in update_fff_scene later
10000	    //this->object_list_changed();
10001	
10002	    // refresh preview
10003	    if (view3D->is_dragging()) // updating scene now would interfere with the gizmo dragging
10004	        delayed_scene_refresh = true;
10005	    else {
10006	        if (this->printer_technology == ptFFF) {
10007	            if (is_finished)
