7967	// Update background processing thread from the current config and Model.
7968	// Returns a bitmask of UpdateBackgroundProcessReturnState.
7969	unsigned int Plater::priv::update_background_process(bool force_validation, bool postpone_error_messages, bool switch_print)
7970	{
7971	    // bitmap of enum UpdateBackgroundProcessReturnState
7972	    unsigned int return_state = 0;
7973	
7974	    // If the update_background_process() was not called by the timer, kill the timer,
7975	    // so the update_restart_background_process() will not be called again in vain.
7976	    background_process_timer.Stop();
7977	    // Update the "out of print bed" state of ModelInstances.
7978	    update_print_volume_state();
7979	    // Apply new config to the possibly running background task.
7980	    bool               was_running = background_process.running();
7981	    //BBS: add the switch print logic before Print::Apply
7982	    BOOST_LOG_TRIVIAL(info) << __FUNCTION__ << boost::format(": enter, force_validation=%1% postpone_error_messages=%2%, switch_print=%3%, was_running=%4%")%force_validation %postpone_error_messages %switch_print %was_running;
7983	    if (switch_print)
7984	    {
7985	        //BBS: update the current print to the current plate
7986	        this->partplate_list.update_slice_context_to_current_plate(background_process);
7987	        this->preview->update_gcode_result(partplate_list.get_current_slice_result());
7988	    }
7989	
7990	    background_process.fff_print()->set_check_multi_filaments_compatibility(wxGetApp().app_config->get("enable_high_low_temp_mixed_printing") == "false");
7991	
7992	    Print::ApplyStatus invalidated;
7993	    const auto& preset_bundle = wxGetApp().preset_bundle;
7994	    if (preset_bundle->get_printer_extruder_count() > 1) {
7995	        PartPlate* cur_plate = background_process.get_current_plate();
7996	        std::vector<int> f_maps = cur_plate->get_real_filament_maps(preset_bundle->project_config);
7997	        invalidated = background_process.apply(this->model, preset_bundle->full_config(false, f_maps));
