15015	        return;
15016	
15017	    //if (get_view3D_canvas3D()->get_gizmos_manager().is_in_editing_mode(true))
15018	    //    return;
15019	
15020	    if (p->process_completed_with_error == p->partplate_list.get_curr_plate_index())
15021	        return;
15022	
15023	    // If possible, remove accents from accented latin characters.
15024	    // This function is useful for generating file names to be processed by legacy firmwares.
15025	    fs::path default_output_file;
15026	    try {
15027	        // Update the background processing, so that the placeholder parser will get the correct values for the ouput file template.
15028	        // Also if there is something wrong with the current configuration, a pop-up dialog will be shown and the export will not be performed.
15029	        unsigned int state = this->p->update_restart_background_process(false, false);
15030	        if (state & priv::UPDATE_BACKGROUND_PROCESS_INVALID)
15031	            return;
