15085	        p->last_output_path = output_path.string();
15086	        p->last_output_dir_path = output_path.parent_path().string();
15087	        p->export_gcode(output_path, path_on_removable_media);
15088	        // Storing a path to AppConfig either as path to removable media or a path to internal media.
15089	        // is_path_on_removable_drive() is called with the "true" parameter to update its internal database as the user may have shuffled the external drives
15090	        // while the dialog was open.
15091	        appconfig.update_last_output_dir(output_path.parent_path().string(), path_on_removable_media);
15092	
15093	        try {
15094	            json j;
15095	            auto printer_config = Slic3r::GUI::wxGetApp().preset_bundle->printers.get_edited_preset_with_vendor_profile().preset;
15096	            if (printer_config.is_system) {
15097	                j["printer_preset"] = printer_config.name;
15098	            } else {
15099	                j["printer_preset"] = printer_config.config.opt_string("inherits");
15100	            }
15101	
15102	            PresetBundle *preset_bundle = wxGetApp().preset_bundle;
15103	            if (preset_bundle) {
15104	                j["gcode_printer_model"] = preset_bundle->printers.get_edited_preset().get_printer_type(preset_bundle);
15105	            }
15106	            NetworkAgent *agent = wxGetApp().getAgent();
15107	        } catch (...) {}
15108	
15109	    }
15110	}
