15210	Preset *get_printer_preset(const MachineObject *obj)
15211	{
15212	    if (!obj)
15213	        return nullptr;
15214	
15215	    Preset       *printer_preset = nullptr;
15216	
15217	    PresetBundle *preset_bundle  = wxGetApp().preset_bundle;
15218	    for (auto printer_it = preset_bundle->printers.begin(); printer_it != preset_bundle->printers.end(); printer_it++) {
15219	        // only use system printer preset
15220	        if (!printer_it->is_system)
15221	            continue;
15222	
15223	        ConfigOption       *printer_nozzle_opt  = printer_it->config.option("nozzle_diameter");
15224	        ConfigOptionFloats *printer_nozzle_vals = nullptr;
15225	        if (printer_nozzle_opt) printer_nozzle_vals = dynamic_cast<ConfigOptionFloats *>(printer_nozzle_opt);
15226	        std::string model_id = printer_it->get_current_printer_type(preset_bundle);
15227	
15228	        std::string printer_type = obj->get_show_printer_type();
15229	        bool nozzle_diameter_matches_or_unknown = printer_nozzle_vals && obj->GetExtderSystem()->NozzleDiameterMatchesOrUnknown(0, printer_nozzle_vals->get_at(0));
15230	        if (model_id.compare(printer_type) == 0 && nozzle_diameter_matches_or_unknown) {
15231	            printer_preset = &(*printer_it);
15232	        }
15233	    }
15234	    return printer_preset;
15235	}
