167	PrintActionState StatusRow::action_state() const
168	{
169	    PrintActionState state;
170	    auto& plates = m_plater.get_partplate_list();
171	    auto* plate = plates.get_curr_plate();
172	    state.slicing = m_plater.is_background_process_slicing();
173	    state.plate_number = plates.get_curr_plate_index() + 1;
174	    state.plate_count = plates.get_plate_count();
175	    const bool editable = !m_plater.only_gcode_mode() && !m_plater.using_exported_file();
176	    for (int i = 0; i < state.plate_count; ++i) {
177	        auto* item = plates.get_plate(i);
178	        if (item->is_slice_result_valid()) ++state.sliced_count;
179	        if (editable && item->can_slice() && !item->is_slice_result_valid()) state.can_slice_all = true;
180	    }
181	    if (plate) {
182	        state.sliced = plate->is_slice_result_valid();
183	        state.can_slice = editable && plate->can_slice();
184	        state.can_print = plate->is_slice_result_ready_for_print();
185	        state.can_export = plate->is_slice_result_ready_for_export();
186	    }
187	    auto* presets = wxGetApp().preset_bundle;
188	    // Match the native print-all backend support. Other legacy hosts accept
189	    // only one plate, even when several valid slices exist.
190	    bool supports_all = presets && presets->use_bbl_network();
191	    if (presets && !supports_all) {
192	        const auto& config = presets->printers.get_edited_preset().config;
193	        const auto* host = config.option<ConfigOptionEnum<PrintHostType>>("host_type");
194	        supports_all = host && host->value == htSimplyPrint;
195	    }
196	    state.can_print_all = supports_all && plates.is_all_slice_results_ready_for_print();
197	    return state;
198	}
