266	void StatusRow::layout_header()
267	{
268	    const int margin = FromDIP(16), gap = FromDIP(8), height = GetClientSize().y;
269	    auto place = [height](HeaderButton* button, int x, int width = -1) {
270	        wxSize size = button->GetBestSize();
271	        if (width >= 0) size.x = width;
272	        button->SetSize(x,(height-size.y)/2,size.x,size.y);
273	    };
274	    int right = GetClientSize().x-margin-m_overflow_button->GetBestSize().x;
275	    place(m_overflow_button,right);
276	    right -= gap;
277	    if (m_agent_toggle->IsShown()) {
278	        right -= m_agent_toggle->GetBestSize().x;
279	        place(m_agent_toggle,right);
280	        right -= gap;
281	    }
282	    if (m_menu_button->IsShown()) {
283	        right -= m_menu_button->GetBestSize().x;
284	        place(m_menu_button,right);
285	    }
286	    right -= m_slice_button->GetBestSize().x;
287	    place(m_slice_button,right);
288	    place(m_home_button,margin);
289	    const int left = margin+m_home_button->GetBestSize().x+gap;
290	    const int available = std::max(0,right-gap-left);
291	    const int width = std::min(m_chip->GetBestSize().x,available);
292	    const wxSize chip = m_chip->GetBestSize();
293	    m_chip->SetSize(left+(available-width)/2,(height-chip.y)/2,width,chip.y);
