310	// The chip renders Orca's own selection and nothing else: the printer, and
311	// one dot per project slot. Nothing here writes; a change goes through the
312	// filament menu and SetupCommands.
313	void StatusRow::refresh_chip()
314	{
315	    const auto printer = SetupCommands::current_printer();
316	    // One nozzle size is said once; a printer with several says each.
317	    std::vector<double> sizes = printer.nozzles;
318	    std::sort(sizes.begin(), sizes.end());
319	    sizes.erase(std::unique(sizes.begin(), sizes.end()), sizes.end());
320	    wxString nozzle;
321	    for (double size : sizes)
322	        nozzle += (nozzle.empty() ? wxString() : wxString(" / ")) + wxString::Format("%g", size);
323	    wxString printer_tooltip = printer.nickname;
324	    if (!nozzle.empty())
325	        printer_tooltip += middle_dot() + nozzle + " mm " + (sizes.size() > 1 ? _L("nozzles") : _L("nozzle"));
326	    m_chip->set_printer(printer.nickname, printer.valid ? nozzle : wxString{}, printer_tooltip);
327	
328	    const auto slots = SetupCommands::filament_slots();
329	    std::vector<ChipSlot> chip_slots;
330	    for (const auto& slot : slots)
331	        chip_slots.push_back({slot.filament.preset_name, std::string(slot.filament.alias.ToUTF8()),
332	                              std::string(slot.colour.ToUTF8()), slot.used});
333	    const FilamentChipModel model = describe_filament_chip(chip_slots);
334	    const wxString label = !model.name.empty() ? wxString::FromUTF8(model.name)
335	                                               : wxString::Format(wxPLURAL("%d filament", "%d filaments", int(model.filaments)),
336	                                                                  int(model.filaments));
337	    // Hover names every slot uncut. The swatches the design draws beside each
338	    // name are the dots on the chip itself; a tooltip carries text only.
339	    wxString tooltip;
340	    if (slots.size() == 1) {
341	        tooltip = slots.front().filament.alias;
342	    } else {
343	        const auto used = std::count_if(slots.begin(), slots.end(), [](const auto& slot) { return slot.used; });
344	        tooltip = used > 0 ? wxString::Format(_L("%d of %d slots on this plate"), int(used), int(slots.size()))
345	                           : wxString::Format(_L("%d slots"), int(slots.size()));
346	        for (const auto& slot : slots) {
347	            tooltip += wxString::Format("\n%d  %s", int(slot.index + 1), slot.filament.alias);
348	            if (slot.nozzle > 0.)
349	                tooltip += middle_dot() + wxString::Format("%g", slot.nozzle);
350	            if (used > 0 && !slot.used)
351	                tooltip += middle_dot() + _L("not on this plate");
352	        }
353	    }
354	    m_chip->set_filaments(model, label, tooltip);
355	}
