373	// One grey line per menu visit that changed a filament, never one per click,
374	// and none for a colour-only visit: the plan did not change. The chip and the
375	// pinned card already follow Orca's own settings-changed notification; the
376	// line reports, and never offers to undo, because the selection belongs to
377	// the chip.
378	void StatusRow::on_filament_visit(const FilamentMenu::Visit& visit)
379	{
380	    refresh();
381	    if (!m_note_sink || visit.filaments.empty()) return;
382	    const auto slots  = SetupCommands::filament_slots();
383	    const bool single = slots.size() == 1;
384	    auto name_of = [&](std::size_t slot) {
385	        return slot < slots.size() ? slots[slot].filament.alias : wxString::FromUTF8(visit.filaments.at(slot));
386	    };
387	    wxString note;
388	    wxString colour;
389	    if (visit.filaments.size() == 1) {
390	        const std::size_t slot = visit.filaments.begin()->first;
391	        note = single ? wxString::Format(_L("Filament is now %s."), name_of(slot))
392	                      : wxString::Format(_L("Slot %d is now %s."), int(slot + 1), name_of(slot));
393	        if (slot < slots.size()) {
394	            colour = slots[slot].colour;
395	            if (!slots[slot].filament.material.empty())
396	                note += " " + wxString::Format(_L("Heat and cooling follow %s; walls and infill unchanged."),
397	                                               slots[slot].filament.material);
398	        }
399	    } else {
400	        wxString changed;
401	        for (const auto& [slot, preset] : visit.filaments)
402	            changed += (changed.empty() ? wxString() : wxString(", ")) +
403	                       wxString::Format(_L("slot %d %s"), int(slot + 1), name_of(slot));
404	        note = wxString::Format(_L("Filaments changed: %s."), changed);
405	    }
406	    note += " " + _L("Slice again when ready.");
407	    m_note_sink(note, colour);
408	}
