422	void StatusRow::request_action(PrintAction action)
423	{
424	    const auto actions = primary_print_action(action_state());
425	    const auto eligible = [action](const PrintActionItem& item) { return item.action == action && item.enabled; };
426	    if (!eligible(actions.primary) && std::none_of(actions.menu.begin(), actions.menu.end(), eligible)) return;
427	    switch (action) {
428	    case PrintAction::Slice: request_slice(); return;
429	    case PrintAction::SliceAll: request_slice(true); return;
430	    case PrintAction::Cancel: m_plater.cancel_slicing(); return;
431	    case PrintAction::Print:
432	    case PrintAction::PrintAll: {
433	        auto& presets = *wxGetApp().preset_bundle;
434	        const auto* host = presets.printers.get_edited_preset().config.option<ConfigOptionString>("print_host");
435	        if (!presets.use_bbl_network() && (!host || host->value.empty())) {
436	            wxMessageBox(_L("Configure a printer connection in Printer settings before printing. You can also export the sliced file."),
437	                         _L("Printer connection required"), wxOK | wxICON_INFORMATION, this);
438	            return;
439	        }
440	        SimpleEvent event(action == PrintAction::Print ? EVT_GLTOOLBAR_PRINT_PLATE : EVT_GLTOOLBAR_PRINT_ALL);
441	        m_plater.GetEventHandler()->ProcessEvent(event); // native confirmation; never an upload shortcut
442	        return;
443	    }
444	    case PrintAction::Export: {
445	        SimpleEvent event(EVT_GLTOOLBAR_EXPORT_SLICED_FILE);
446	        m_plater.GetEventHandler()->ProcessEvent(event);
447	        return;
448	    }
449	    }
450	}
