452	void StatusRow::request_slice(bool all)
453	{
454	    const auto state = action_state();
455	    if (state.slicing || state.sliced || (all ? !state.can_slice_all : !state.can_slice)) return;
456	    m_plater.exit_gizmo();
457	    m_plater.update(true, true);
458	    request_prepare();
459	    SimpleEvent event(all ? EVT_GLTOOLBAR_SLICE_ALL : EVT_GLTOOLBAR_SLICE_PLATE);
460	    m_plater.GetEventHandler()->ProcessEvent(event);
461	    refresh();
462	}
