329	void ShellController::on_frame_destroy(wxWindowDestroyEvent& event)
330	{
331	    if (event.GetWindow() == m_frame) {
332	        m_runtime_timer.Stop();
333	        m_installed = false;
334	        wxGetApp().show_config_wizard_on_startup = m_saved_show_config_wizard_on_startup;
335	        m_prepare_canvas_presentation.abandon();
336	        // This controller lives in a static slot and outlives every window,
337	        // so whatever it owns that unbinds from the Plater has to go now,
338	        // while the frame's children still exist: wx sends this event from
339	        // the top-level window's destructor, before DestroyChildren. Left in
340	        // place, the slot's destructor ran ~OrcaWorkspaceAdapter against a
341	        // deleted Plater after main had returned -- an access violation at
342	        // process exit in every run that did not detach the shell by hand.
343	        // Same order as uninstall(): the pane and status row first, since
