385	void ShellController::request_agent_pane_width(int width)
386	{
387	    // Remember what the pane can actually take, not what the pointer asked
388	    // for. A drag that runs past the edge of a small window would otherwise
389	    // record a width the pane never had, and the pane would claim it -- at the
390	    // workspace's expense -- the next time the window grew enough to allow it.
391	    // A width the window merely cannot afford right now is a different case:
392	    // apply_agent_pane_width() narrows the pane without touching the
393	    // preference, so growing the window restores the width the person chose.
394	    m_agent_pane_preferred_width = agent_pane_width_within(width);
