398	void ShellController::apply_agent_pane_width()
399	{
400	    if (m_theme == nullptr || m_frame == nullptr || m_center_sizer == nullptr || m_agent_pane == nullptr)
401	        return;
402	    if (m_agent_pane_collapsed)
403	        return;
404	    const int width = agent_pane_width_within(m_agent_pane_preferred_width);
405	    m_center_sizer->SetItemMinSize(m_agent_pane, width, -1);
406	    // Lay out from the frame, not from m_center_sizer. A sizer lays itself out
407	    // against the dimension it was last given, which during a frame resize is
408	    // still the previous client width; the frame reads the current one from the
409	    // window. Laying out the sizer directly leaves the workspace and the
410	    // divider sized for the old width while the pane takes the new one, so they
411	    // overlap, and the next resize swaps which of them is stale.
412	    m_frame->Layout();
413	}
