415	void ShellController::set_agent_pane_collapsed(bool collapsed)
416	{
417	    if (m_agent_pane == nullptr || m_agent_resize_handle == nullptr || m_agent_pane_collapsed == collapsed)
418	        return;
419	    m_agent_pane_collapsed = collapsed;
420	    // Hidden, never destroyed: the conversation, the loaded page, and the MCP
421	    // runtime all outlive a collapse. A hidden sizer item takes no space, so
422	    // the workspace grows into the whole width with no second width policy.
423	    m_agent_pane->Show(!collapsed);
424	    m_agent_resize_handle->Show(!collapsed);
425	    if (m_status_row != nullptr)
426	        m_status_row->set_agent_pane_collapsed(collapsed);
427	    // Expanding re-applies the width policy, which lays out on its way; a
428	    // collapsed pane has no width to apply, so it lays out here.
429	    if (collapsed)
430	        m_frame->Layout();
431	    else
432	        apply_agent_pane_width();
433	}
